/bin/zsh -lc "cat > tb.sv <<'EOF'
"'`timescale 1ns/1ps
module tb;
  reg clk = 0;
  reg rst_n = 0;
  reg [7:0] data_in = 0;
  reg valid_a = 0;
  reg ready_b = 0;
  wire ready_a;
  wire valid_b;
  wire [9:0] data_out;

  TopModule dut (
    .clk(clk), .rst_n(rst_n), .data_in(data_in), .valid_a(valid_a), .ready_b(ready_b),
    .ready_a(ready_a), .valid_b(valid_b), .data_out(data_out)
  );

  always #5 clk = ~clk;

  task send(input [7:0] v);
    begin
      @(negedge clk);
      data_in = v;
      valid_a = 1;
      while (!ready_a) @(negedge clk);
      @(negedge clk);
      valid_a = 0;
    end
  endtask

  initial begin
    $display("start");
    repeat (2) @(negedge clk);
    rst_n = 1;

    ready_b = 1;
    send(8'"'d1);
    send(8'd2);
    send(8'd3);
    send(8'd4);
    @(posedge clk);
    if ("'!(valid_b && data_out == 10'"'d10)) begin
      "'$display("FAIL first sum valid_b=%0d data_out=%0d", valid_b, data_out);
      $finish(1);
    end

    @(negedge clk);
    ready_b = 0;
    data_in = 8'"'d9;
    valid_a = 1;
    @(posedge clk);
    if ("'!ready_a) begin
      $display("FAIL ready_a deasserted unexpectedly when no pending output");
      $finish(1);
    end
    @(negedge clk);
    valid_a = 0;

    ready_b = 1;
    send(8'"'d1);
    send(8'd1);
    send(8'd1);
    @(posedge clk);
    if ("'!(valid_b && data_out == 10'"'d12)) begin
      "'$display("FAIL second sum valid_b=%0d data_out=%0d", valid_b, data_out);
      $finish(1);
    end

    $display("PASS");
    $finish;
  end
endmodule
EOF
iverilog -g2012 -o simv TopModule.sv tb.sv && vvp simv'

